function initializeFactors(train, numFactors = NUM_FACTORS) {
  const globalMean = train.length
    ? train.reduce((acc, r) => acc + r.rating, 0) / train.length
    : 0;
  // Repeated "Train" clicks must not leak the previous variables.
  if (model) {
    tf.dispose([model.userFactors, model.itemFactors].filter(Boolean));
  }
  const maxMovieId = movies.reduce((m, x) => Math.max(m, x.id), 0);
  model = {
    userFactors: tf.variable(tf.randomNormal([numUsers + 1, numFactors], 0, 0.05)),
    itemFactors: tf.variable(tf.randomNormal([maxMovieId + 1, numFactors], 0, 0.05)),
    globalMean,
  };
  return model;
}

 *  - Shuffling the batch order each epoch is allowed and usually helps.
 *  - Guard `train.length === 0` by returning an empty history.
 *  - Checkpointing: while epochs run, the weights of the epoch with the lowest
 *    `valRMSE` so far are snapshotted and restored when training ends, so the
 *    model the page holds afterwards IS the validation-selected checkpoint
 *    (when `val` is empty the final epoch is kept). `minimize` is called with
 *    `returnCost = false`, which makes it return `undefined` and dispose the
 *    cost tensor internally — nothing may be chained onto that return value.
 *
 * @param {Rating[]} train
 * @param {Rating[]} val
 * @param {TrainOptions} opts
 * @returns {HistoryRow[]}
 */
function trainMF(train, val, opts) {
  if (!train || train.length === 0) return [];

  const { epochs, lr, reg, batchSize } = opts;
  const uRows = model.userFactors.shape[0];
  const iRows = model.itemFactors.shape[0];

  // Encode the training set once as typed arrays; ratings whose ids have no
  // factor row can never be predicted, so they are dropped up front.
  const userIds = [];
  const movieIds = [];
  const targets = [];
  for (const r of train) {
    if (r.userId < 0 || r.userId >= uRows || r.movieId < 0 || r.movieId >= iRows) continue;
    userIds.push(r.userId);
    movieIds.push(r.movieId);
    targets.push(r.rating);
  }
  const n = userIds.length;

  const size = Math.max(1, Math.min(Math.round(batchSize) || 1, n));
  const numBatches = Math.ceil(n / size);
  const optimizer = tf.train.adam(lr);
  const order = Array.from({ length: n }, (_, i) => i);
  const hasVal = !!val && val.length > 0;

  let bestVal = Number.POSITIVE_INFINITY;
  let savedUsers = null;
  let savedItems = null;
  const dropSnapshots = () => {
    tf.dispose([savedUsers, savedItems].filter(Boolean));
    savedUsers = null;
    savedItems = null;
  };

  try {
    for (let epoch = 1; epoch <= epochs; epoch++) {
      // Fisher-Yates shuffle so each epoch visits the ratings in a new order.
      for (let i = n - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        const tmp = order[i];
        order[i] = order[j];
        order[j] = tmp;
      }

      for (let b = 0; b < numBatches; b++) {
        const slice = order.slice(b * size, b * size + size);
        optimizer.minimize(
          () => {
            const uIdx = tf.tensor1d(slice.map((k) => userIds[k]), "int32");
            const iIdx = tf.tensor1d(slice.map((k) => movieIds[k]), "int32");
            const y = tf.tensor1d(slice.map((k) => targets[k]), "float32");
            const u = tf.gather(model.userFactors, uIdx);
            const q = tf.gather(model.itemFactors, iIdx);
            const pred = u.mul(q).sum(1).add(model.globalMean);
            const mse = tf.losses.meanSquaredError(y, pred);
            const l2 = model.userFactors
              .square()
              .sum()
              .add(model.itemFactors.square().sum())
              .mul(reg);
            return mse.add(l2);
          },
          false,
          [model.userFactors, model.itemFactors],
        );
      }

      const row = {
        epoch,
        trainRMSE: computeRMSEFor(train),
        valRMSE: computeRMSEFor(val),
      };
      trainingHistory.push(row);

      // Snapshot the current weights whenever they are the best on validation
      // so far (with no validation signal the latest epoch is kept).
      if (!hasVal || row.valRMSE < bestVal) {
        if (Number.isFinite(row.valRMSE)) bestVal = Math.min(bestVal, row.valRMSE);
        dropSnapshots();
        savedUsers = model.userFactors.clone();
        savedItems = model.itemFactors.clone();
      }
    }
  } finally {
    if (savedUsers && savedItems) {
      model.userFactors.assign(savedUsers);
      model.itemFactors.assign(savedItems);
    }
    dropSnapshots();
    optimizer.dispose();
  }

  return trainingHistory;
}

