edits.newText:
function recommendTopK(userId, K = 10) {
  if (!isTfModel(model) || !K || K <= 0) return [];
  const uid = Number(userId);
  const uRows = model.userFactors.shape[0];
  const iRows = model.itemFactors.shape[0];
  const F = model.userFactors.shape[1];
  if (!Number.isFinite(uid) || uid < 0 || uid >= uRows) return [];

  const known = new Set(movies.map((m) => m.id));
  const excluded = new Set();
  for (const r of trainSet) if (r.userId === uid) excluded.add(r.movieId);
  for (const r of valSet) if (r.userId === uid) excluded.add(r.movieId);

  const maskData = new Float32Array(iRows);
  let validCount = 0;
  for (let id = 0; id < iRows; id++) {
    if (known.has(id) && !excluded.has(id)) {
      maskData[id] = 1;
      validCount++;
    }
  }
  if (validCount === 0) return [];
  const k = Math.min(K, validCount);

  return tf.tidy(() => {
    const userRow = model.userFactors.slice([uid, 0], [1, F]); // [1, F]
    const scores = model.itemFactors
      .matMul(userRow, false, true) // [rows, 1]
      .squeeze() // [rows]
      .add(model.globalMean);
    const mask = tf.tensor1d(maskData, "float32");
    const masked = scores.mul(mask).add(mask.sub(1).mul(1e9)); // excluded -> ~-1e9
    const { values, indices } = tf.topk(masked, k);
    const topValues = values.dataSync();
    const topIds = indices.dataSync();

    const out = [];
    for (let j = 0; j < k; j++) {
      const id = topIds[j];
      if (!maskData[id]) continue; // safety: never emit a masked id
      out.push({ movieId: id, title: movieTitle(id), score: topValues[j] });
    }
    return out;
  });
}

