edits.newText:
function recallAtK(K = 10) {
  const result = {
    overallRecall: 0,
    perUser: [],
    excluded: { unseenIds: [], usersWithoutRelevant: [] },
  };

  // Candidate pool: every movie id that appears anywhere in the training split
  // (global pool — it decides which relevant test items CAN count, and which
  // users are evaluable; the Top-K list itself comes from `recommendTopK`).
  const pool = new Set(trainSet.map((r) => r.movieId));

  const relevantByUser = new Map(); // userId -> Set(movieId) of relevant candidates
  const unseen = new Set();
  const testUsers = new Set();
  for (const r of testSet) {
    testUsers.add(r.userId);
    if (r.rating < 4.0) continue;
    if (!pool.has(r.movieId)) {
      unseen.add(r.movieId); // can never be recommended from a training-only pool
      continue;
    }
    if (!relevantByUser.has(r.userId)) relevantByUser.set(r.userId, new Set());
    relevantByUser.get(r.userId).add(r.movieId);
  }

  result.excluded.unseenIds = Array.from(unseen).sort((a, b) => a - b);
  result.excluded.usersWithoutRelevant = Array.from(testUsers)
    .filter((u) => !relevantByUser.has(u) || relevantByUser.get(u).size === 0)
    .sort((a, b) => a - b);

  let sum = 0;
  let count = 0;
  for (const [u, relevant] of relevantByUser) {
    if (relevant.size === 0) continue;
    const recIds = new Set(recommendTopK(u, K).map((r) => r.movieId));
    let hit = 0;
    for (const movieId of relevant) if (recIds.has(movieId)) hit++;
    result.perUser.push({ userId: u, relevant: relevant.size, hit });
    sum += hit / relevant.size;
    count++;
  }
  result.overallRecall = count ? sum / count : 0;
  return result;
}

