  // (b) RMSE fixture by hand: predictions [4,2] vs actual [3,4]
  //     errors 1,-2 -> (1+4)/2 = 2.5 -> sqrt = 1.5811
  withFixture({
    train: [{userId:1,movieId:1,rating:3,timestamp:1},{userId:1,movieId:2,rating:4,timestamp:2}],
    model: fixtureModel({1:1}, {1:3,2:1}, 1),  // preds: 1+3=4, 1+1=2
  }, () => {
    const r = computeRMSEFor(trainSet);
    const expect = Math.sqrt(((4-3)**2 + (2-4)**2) / 2);
    if (Math.abs(r - expect) > 1e-6) throw new Error('rmse fixture: got ' + r + ' expected ' + expect);
    notes.push('RMSE fixture ok: sqrt((1+4)/2) = ' + expect.toFixed(6));
  });

  // (c) Recall@K fixture by hand, 3 movies, K=2.
  //     user1 train-rated movie1 (excluded), relevant test movie2 (in pool via
  //     user2), distractor movie3 scores higher. Top-2 = [3, 2] -> hit 1/1.
