// Real browser run: python http.server + headless Chrome over CDP.
// Clicks the actual buttons (Run tests, Train, Recommend, Recall), reads the
// real DOM, and dumps numbers for the report. No page code is patched.
import { spawn } from 'node:child_process';
import fs from 'node:fs';
import http from 'node:http';

const PORT = 8123, DEBUG_PORT = 9223;
const log = (...a) => console.log(...a);

