  for (const u of [1, heavy.user]) {
    await evaljs(`document.getElementById('user-select').value = String(${u})`);
    await click('recommend-btn'); await sleep(700);
    report[u] = {
      dom: (await getText('recommendations')).replace(/\s+/g, ' '),
      recs: JSON.parse(await evaljs(`JSON.stringify(recommendTopK(${u}, 10))`)),
      overlap: await evaljs(`(function(){const seen=new Set([...trainSet,...valSet].filter(r=>r.userId===${u}).map(r=>r.movieId));return recommendTopK(${u},10).filter(r=>seen.has(r.movieId)).length;})()`),
      history: JSON.parse(await evaljs(`(function(){
        const seen=[...trainSet,...valSet].filter(r=>r.userId===${u});
        const rows=seen.map(r=>{const m=movies.find(m=>m.id===r.movieId);return{id:r.movieId,title:m?m.title:'',genres:m?m.genres:[],rating:r.rating};});
        const g={};rows.forEach(x=>x.genres.forEach(k=>g[k]=(g[k]||0)+1));
        return JSON.stringify({n:rows.length,mean:+(rows.reduce((a,x)=>a+x.rating,0)/rows.length).toFixed(3),
          genres:Object.entries(g).sort((a,b)=>b[1]-a[1]).slice(0,6),
          topRated:rows.slice().sort((a,b)=>b.rating-a.rating).slice(0,8)});})()`)),
      recGenres: JSON.parse(await evaljs(`(function(){
        const recs=recommendTopK(${u},10);const g={};
        const items=recs.map(r=>{const m=movies.find(m=>m.id===r.movieId);m.genres.forEach(k=>g[k]=(g[k]||0)+1);
          return{id:r.movieId,title:m.title,genres:m.genres,score:+r.score.toFixed(4)};});
        return JSON.stringify({genres:Object.entries(g).sort((a,b)=>b[1]-a[1]),items});})()`)),
    };
  }
  fs.writeFileSync('/tmp/a05-work/recs-verify.json', JSON.stringify(report, null, 2));
  for (const u of [1, heavy.user]) {
    const r = report[u];
    log(`--- user ${u}: ${r.history.n} train+val ratings, mean ${r.history.mean}, overlap(train/val ∩ top10)=${r.overlap}`);
    log('    past genres:', r.history.genres.map(([k,v])=>`${k}:${v}`).join(' '));
    for (const it of r.recs) log(`    ${it.score.toFixed(4)}  ${it.title}`);
  }

  // strict Recall@10
  const tR = Date.now();
  await click('recall-btn');
  for (let i = 0; i < 200; i++) { const s = await getText('recall-results'); if (s && !s.includes('Train the model')) break; await sleep(400); }
  log('RECALL DOM head:', (await getText('recall-results')).replace(/\s+/g, ' ').slice(0, 160));
  log('RECALL strict:', await evaljs(`(function(){const r=recallAtK(10);return JSON.stringify({overallRecall:+r.overallRecall.toFixed(6),users:r.perUser.length,totalRelevant:r.perUser.reduce((a,x)=>a+x.relevant,0),totalHits:r.perUser.reduce((a,x)=>a+x.hit,0),unseenIds:r.excluded.unseenIds.length,usersWithoutRelevant:r.excluded.usersWithoutRelevant.length});})()`));
  log('recall wall: ' + ((Date.now()-tR)/1000).toFixed(1) + 's');

  await click('run-tests'); await sleep(1200);
  const tl = await getText('testLog');
  log('TESTS(after train):', tl.split('\n')[0]);
  fs.writeFileSync('/tmp/a05-work/testlog-verify.txt', tl);
  fs.writeFileSync('/tmp/a05-work/verify-summary.json', JSON.stringify({ chrome: ver.product, backend: await evaljs('tf.getBackend()'), run1: r1, run2: r2 }, (k,v)=>typeof v==='number'?v:v, 2));
  await send('Target.closeTarget', { targetId });
} catch (e) { log('FATAL', e.message); process.exitCode = 1; }
finally { chrome.kill(); server.close(); setTimeout(() => process.exit(process.exitCode || 0), 500); }
EOF
